void Rivet::Glyphux::Register()
{
	static const bool bRegistered = []
	{
		static const Detail::FModuleTable ModuleTable = {&Detail::Log};
		rivet_Glyphux_init(&ModuleTable);
		rivet_Glyphux_GlyphuxTextComponent_register(&Detail::Table_GlyphuxTextComponent);
		rivet_Glyphux_GlyphuxTextBlock_register(&Detail::Table_GlyphuxTextBlock);
		rivet_Glyphux_base_Gpu_register(&Detail::BaseTable_Gpu);
		rivet_Glyphux_base_BlockSink_register(&Detail::BaseTable_BlockSink);
		rivet_Glyphux_base_ComponentSink_register(&Detail::BaseTable_ComponentSink);
		return true;
	}();
	(void)bRegistered;
}

void Rivet::Glyphux::Init(UGlyphuxSubsystem* InSubsystem)
{
	Register();
	rivet_Glyphux_fn_init(Rivet::ToObj(InSubsystem));
}

void Rivet::Glyphux::Tick()
{
	Register();
	rivet_Glyphux_fn_tick();
}

void Rivet::Glyphux::Flush()
{
	Register();
	rivet_Glyphux_fn_flush();
}

void Rivet::Glyphux::Shutdown()
{
	Register();
	rivet_Glyphux_fn_shutdown();
}

FString Rivet::Glyphux::Stats()
{
	Register();
	return Rivet::ToFString(rivet_Glyphux_fn_stats());
}

